<script setup lang="ts">
import { computed,ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowUpRight,ArrowRight,Plus,Box,Database,Activity,CheckCheck,Cpu,ChevronDown,Pause,Play,Clock,Layers,CheckCircle2,Info,Terminal,Download } from '@lucide/vue'
import WorkspaceSpotlight from '../components/overview/WorkspaceSpotlight.vue'
import MetricChart from '../components/charts/MetricChart.vue'
import DetailModal from '../components/common/DetailModal.vue'
import { useDemoStore } from '../stores/demo'
import type { JobStatus } from '../types'
import JobLossChart from '../components/overview/JobLossChart.vue'
const router=useRouter();const store=useDemoStore();const range=ref('7');const jobFilter=ref('all')
const detail=ref<{title:string;details:Record<string,string|number>}|null>(null)
const stats=computed(()=>[{label:'已注册模型',value:String(store.models.length).padStart(2,'0'),caption:'已注册训练模型',icon:Box,foot:'Pi0.5 · GR00T · LingBot',color:'blue'},{label:'可用数据集',value:String(store.datasets.length).padStart(2,'0'),caption:'可用演示数据集',icon:Database,foot:`${store.datasets.reduce((n,d)=>n+d.episodes,0).toLocaleString()} episodes · Mock`,color:'purple'},{label:'运行中任务',value:String(store.jobs.filter(j=>j.status==='Running').length).padStart(2,'0'),caption:'正在运行的模拟任务',icon:Activity,foot:`已使用 ${store.gpus.filter(g=>g.utilization>0).length} / 4 张 GPU`,color:'blue'},{label:'已完成任务',value:String(store.jobs.filter(j=>j.status==='Completed').length).padStart(2,'0'),caption:'累计完成的演示任务',icon:CheckCheck,foot:'当前工作空间完成任务',color:'green'}])
const statusLabels: Record<JobStatus, string> = { Pending: '等待中', Running: '运行中', Completed: '已完成', Failed: '失败', Stopped: '已停止' }
const visibleJobs=computed(()=>store.jobs.filter(j=>jobFilter.value==='all'||j.status===jobFilter.value).slice(0,4))
const chartColors=computed(()=>({text:store.dark?'#91a0b6':'#8792a5',grid:store.dark?'#273347':'#eef1f6'}))
const activityOption=computed(()=>{const count=Number(range.value);return {color:['#3974f6','#dce6fc'],grid:{top:18,right:8,bottom:28,left:28},tooltip:{trigger:'axis',axisPointer:{type:'shadow'}},xAxis:{type:'category',data:Array.from({length:count},(_,i)=>{const d=new Date(Date.UTC(2026,10,4));d.setUTCDate(d.getUTCDate()-count+i+1);return `${d.getUTCMonth()+1}/${d.getUTCDate()}`}),axisLabel:{color:chartColors.value.text,fontSize:10,interval:count===7?0:5},axisLine:{show:false},axisTick:{show:false}},yAxis:{type:'value',splitNumber:3,axisLabel:{color:chartColors.value.text,fontSize:10},splitLine:{lineStyle:{color:chartColors.value.grid,type:'dashed'}}},series:[{name:'已完成 · Mock',type:'bar',stack:'jobs',barMaxWidth:22,itemStyle:{borderRadius:[2,2,0,0]},data:Array.from({length:count},(_,i)=>[3,5,2,4,6,3,4][i%7])},{name:'其他任务 · Mock',type:'bar',stack:'jobs',barMaxWidth:22,itemStyle:{borderRadius:[4,4,0,0]},data:Array.from({length:count},(_,i)=>[1,2,1,2,1,1,2][i%7])}]}})
function exportOverview(){const blob=new Blob([JSON.stringify({mode:'DEMO',jobs:store.jobs,gpus:store.gpus},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='robotic-lab-demo-overview.json';a.click();URL.revokeObjectURL(url);store.notify('已导出演示概览 JSON。')}
</script>
<template><div class="page-heading"><div><div class="eyebrow">模型训练工作空间</div><h1>训练控制台<span class="heading-dot">.</span></h1><p>从数据到智能，让每一次训练清晰可见。</p></div><div class="heading-actions"><button class="button" @click="exportOverview"><Download :size="15"/> 导出概览</button><button class="button primary" @click="router.push('/training')"><Plus :size="17"/> 新建训练</button></div></div>
<div class="demo-banner"><span><Info :size="15"/><strong>演示模式</strong><span>你正在浏览 Mock 数据，模型环境与 GPU 均未连接。</span></span><span class="banner-end">前端预览 <ArrowUpRight :size="14"/></span></div>
<WorkspaceSpotlight @inspect="detail={title:'当前实验快照 · Mock',details:{'运行任务':store.jobs.filter(j=>j.status==='Running').length,'GPU 分配':store.jobs.filter(j=>j.status==='Running').map(j=>j.name+' → '+j.gpu).join('；')||'暂无','可用资源':store.gpus.filter(g=>g.utilization===0).map(g=>'GPU '+g.id).join(', ')||'暂无空闲 GPU','最近快照':store.checkpoints[0]?.name??'暂无','说明':'演示数据；未连接真实 GPU'}}"/>
<section class="stats-grid"><article v-for="stat in stats" :key="stat.label" class="stat-card"><div class="stat-top"><span>{{stat.label}}</span><span :class="['stat-icon',stat.color]"><component :is="stat.icon" :size="18"/></span></div><div class="stat-value">{{stat.value}}<span v-if="stat.label==='运行中任务'" class="live-pill"><i></i> 实时模拟</span></div><p>{{stat.caption}}</p><div class="stat-footer"><span :class="{positive:stat.color==='green'}">{{stat.foot}}</span><ArrowUpRight :size="13"/></div></article></section>
<div class="resource-grid"><section class="panel gpu-panel"><div class="section-heading"><div><h2>GPU 资源概览 <span class="small-badge">MOCK</span></h2><p>本地计算资源 · NVIDIA A100 80GB × 4</p></div><button class="icon-button" :aria-label="store.live?'暂停模拟刷新':'恢复模拟刷新'" @click="store.live=!store.live"><Pause v-if="store.live" :size="15"/><Play v-else :size="15"/></button></div><div class="gpu-summary"><div><span class="tiny-dot"></span><strong>{{store.gpus.filter(g=>g.utilization>0).length}} <small>/ 4</small></strong><span>GPU 使用中</span></div><div><strong>{{Math.round(store.gpus.reduce((s,g)=>s+g.utilization,0)/4)}}<small>%</small></strong><span>平均利用率</span></div><div><strong>{{store.gpus.reduce((n,g)=>n+g.memory,0).toFixed(1)}} <small>GB</small></strong><span>已分配显存 / 320 GB</span></div></div><div class="gpu-list"><div v-for="gpu in store.gpus" :key="gpu.id" class="gpu-row"><div class="gpu-label"><Cpu :size="17"/><strong>GPU {{gpu.id}}</strong><span :class="['gpu-state',{idle:gpu.utilization===0}]">{{gpu.utilization===0?'空闲':'使用中'}}</span></div><div class="gpu-meter"><div class="meter-label"><span>利用率</span><strong>{{gpu.utilization}}%</strong></div><div class="progress-track"><div :style="{width:gpu.utilization+'%'}"></div></div></div><div class="gpu-memory"><strong>{{gpu.memory.toFixed(1)}} <span>/ 80 GB</span></strong><span>显存</span></div><span class="temperature">{{gpu.temperature}}°C</span></div></div><div class="panel-foot"><span :class="['tiny-dot',{idle:!store.live}]"></span>{{store.live?'每 2 秒刷新模拟指标':'模拟刷新已暂停'}}<span class="push-right">{{store.tick}} 次更新</span></div></section>
<section class="panel activity-panel"><div class="section-heading"><div><h2>训练活动</h2><p>训练任务活动 · Mock</p></div><label class="select-wrap"><select v-model="range" aria-label="训练活动时间范围"><option value="7">最近 7 天</option><option value="30">最近 30 天</option></select><ChevronDown :size="12"/></label></div><div class="activity-number">{{range==='7'?'37':'159'}}<span>次训练</span><span class="activity-growth">↗ {{range==='7'?'28.6':'18.2'}}%</span></div><MetricChart :option="activityOption"/><div class="chart-legend"><span><i class="blue-dot"></i>已完成</span><span><i class="pale-dot"></i>其他任务</span><span class="push-right">模拟统计</span></div></section></div>
<div class="analysis-grid"><section class="panel jobs-panel"><div class="section-heading"><div><h2>最近任务 <span class="count-badge">{{store.jobs.length}}</span></h2><p>最近的训练实验</p></div><label class="select-wrap"><select v-model="jobFilter" aria-label="筛选最近任务"><option value="all">全部状态</option><option value="Running">运行中</option><option value="Completed">已完成</option></select><ChevronDown :size="12"/></label></div><div class="table-scroll"><table><thead><tr><th>任务 / 模型</th><th>状态</th><th>进度</th><th>Loss</th><th></th></tr></thead><tbody><tr v-for="job in visibleJobs" :key="job.id"><td><button class="job-name" @click="router.push('/jobs/'+job.id)">{{job.name}}</button><div class="table-sub">{{job.id}}<span>·</span>{{job.model}}</div></td><td><span :class="['status',job.status.toLowerCase()]"><i></i>{{statusLabels[job.status]}}</span></td><td><div class="table-progress"><span>{{job.progress}}%</span><div class="progress-track"><div :style="{width:job.progress+'%'}" :class="{complete:job.status==='Completed'}"></div></div></div></td><td class="mono">{{job.loss.toFixed(4)}}</td><td><button class="icon-button" :aria-label="'查看 '+job.id" @click="router.push('/jobs/'+job.id)"><ArrowUpRight :size="16"/></button></td></tr></tbody></table></div><div class="panel-foot">显示 {{visibleJobs.length}} 个演示任务<span class="push-right">全部时间均为演示值</span></div></section>
<JobLossChart/></div>
<div class="bottom-grid"><section class="panel checkpoints-panel"><div class="section-heading"><div><h2>最近 Checkpoints</h2><p>最近保存的模型快照 · Mock</p></div><Layers :size="18" class="muted"/></div><button v-for="cp in store.checkpoints.slice(0,3)" :key="cp.name" class="checkpoint-row" @click="detail={title:cp.name,details:{'模型':cp.model,'训练任务':cp.job,'累计步数':cp.step,'演示大小':cp.size,'存储路径':'/demo/checkpoints/'+cp.name,'说明':'仅为 Mock 元数据，不包含真实权重文件'}}"><span class="checkpoint-icon"><Box :size="17"/></span><span><strong>{{cp.name}}</strong><small>{{cp.model}} <span>·</span> 步数 {{cp.step.toLocaleString()}}</small></span><span class="checkpoint-size">{{cp.size}}</span><ArrowUpRight :size="15"/></button></section><section class="panel events-panel"><div class="section-heading"><div><h2>系统事件</h2><p>工作空间动态 · Mock</p></div><span class="event-badge">演示事件</span></div><div class="event"><span class="event-icon green"><CheckCircle2 :size="15"/></span><div><strong>Checkpoint 保存成功</strong><p>pi05-pick-place-v3 · 步数 30,000</p></div><time>16:42</time></div><div class="event"><span class="event-icon blue"><Play :size="14"/></span><div><strong>训练任务已启动</strong><p>groot-robotwin-finetune · GPU 2</p></div><time>15:08</time></div><div class="event"><span class="event-icon purple"><Terminal :size="15"/></span><div><strong>模拟环境已就绪</strong><p>3 个模型配置已加载 · 未连接真实环境</p></div><time>14:30</time></div></section></div>
<DetailModal v-if="detail" :title="detail.title" :details="detail.details" @close="detail=null"/>
</template>
